function validate([s, pairs]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 100000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase English letters.';
  if (!Array.isArray(pairs) || pairs.length > 100000) return 'pairs may hold at most 100000 pairs.';
  for (const pair of pairs) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each pair has exactly two indices.';
    if (pair.some(v => !Number.isInteger(v) || v < 0 || v >= s.length)) return 'Each index must be between 0 and s.length - 1.';
  }
  return null;
}

