function smallestStringWithSwaps(s, pairs) {
  // Label every position with the smallest index it can reach, relaxing the pairs until nothing changes.
  const label = [];
  for (let i = 0; i < s.length; i++) label.push(i);
  let changed = true;
  while (changed) {
    changed = false;
    for (const [a, b] of pairs) {
      const low = Math.min(label[a], label[b]);
      if (label[a] !== low || label[b] !== low) { label[a] = low; label[b] = low; changed = true; }
    }
  }
  // Within each label, repeatedly place the smallest remaining letter at the leftmost free position.
  const out = s.split('');
  const done = new Set();
  for (let i = 0; i < s.length; i++) {
    if (done.has(label[i])) continue;
    done.add(label[i]);
    const spots = [];
    for (let j = 0; j < s.length; j++) if (label[j] === label[i]) spots.push(j);
    const pool = spots.map(j => s[j]);
    for (const spot of spots) {
      let pick = 0;
      for (let t = 1; t < pool.length; t++) if (pool[t] < pool[pick]) pick = t;
      out[spot] = pool[pick];
      pool.splice(pick, 1);
    }
  }
  return out.join('');
}

