function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 8);
    const alphabet = int(1, 5);
    let s = '';
    for (let i = 0; i < n; i++) s += String.fromCharCode(97 + int(0, alphabet - 1));
    const pairs = [];
    const m = int(0, 7);
    for (let k = 0; k < m; k++) pairs.push([int(0, n - 1), int(0, n - 1)]);
    return [s, pairs];
  }
  const n = int(4000, 6000);
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + int(0, 25));
  const pairs = [];
  const m = 2000;
  // Half the time the pairs stay inside a window, which builds a few large components.
  const span = rand() < 0.5 ? n : int(500, 1500);
  const start = int(0, n - span);
  for (let k = 0; k < m; k++) pairs.push([start + int(0, span - 1), start + int(0, span - 1)]);
  return [s, pairs];
}
